const [d, t1, sr] = await Promise.all([
  tools.pwsh({ command: "Get-Date -Format 'yyyy-MM-dd HH:mm K'; (Get-Date).ToUniversalTime().ToString('u')", description: "Show current local and UTC date" }),
  tools.web_fetch({ url: "https://example.com" }).then(r => ({ ok: true, status: r.statusCode, len: String(r.body?.content ?? "").length })).catch(e => ({ ok: false, err: String(e) })),
  tools.web_search({ queries: [
    "mattpocock skills grill-me handoff triage tdd improve-codebase-architecture 同一个作者",
    "skills.sh find-skills 360万 安装量 2026年10月",
    "LinklyAI best-skills top 100 skills.sh 排行 find-skills 第一",
  ]}),
]);
if (d.kind === "foreground") console.log("DATE:", d.stdout.text.trim());
console.log("FETCH example.com:", JSON.stringify(t1));
console.log("\n=== summary ===\n", sr.content ?? "(none)");
for (const s of sr.sources) console.log(`\n--- ${s.title ?? ""}\n${s.url}\n${s.snippet ?? ""}`);
